-- Restringe somente o bucket fiscal, mesmo se houver políticas permissivas de outros aplicativos.
create policy fs_storage_read_guard on storage.objects as restrictive for select to authenticated using(bucket_id<>'fiscal-prints' or (public.fs_is_member() and exists(select 1 from public.fs_attachments a where a.path=storage.objects.name and (a.committed or a.uploaded_by=auth.uid()))));
create policy fs_storage_insert_guard on storage.objects as restrictive for insert to authenticated with check(bucket_id<>'fiscal-prints' or (public.fs_is_member() and exists(select 1 from public.fs_attachments a where a.path=storage.objects.name and a.uploaded_by=auth.uid() and not a.committed)));
create policy fs_storage_delete_guard on storage.objects as restrictive for delete to authenticated using(bucket_id<>'fiscal-prints' or (public.fs_is_member() and exists(select 1 from public.fs_attachments a where a.path=storage.objects.name and a.uploaded_by=auth.uid() and not a.committed)));
